INSERT INTO projects (id, title, title_ar, category, category_ar, subcategory, subcategory_ar, description, description_ar, image, year, location, location_ar, client, client_ar, size, size_ar, duration, duration_ar, detailedDescription, detailedDescription_ar, challenge, challenge_ar, solution, solution_ar, features, features_ar, materials, materials_ar, awards, awards_ar, team, team_ar, gallery, clientQuote, clientQuote_ar, clientName, clientName_ar, status, sortOrder, createdAt) VALUES (1, 'REC. HEAVEN', 'جنة الترفيه', 'interior-design', 'تصميم داخلي', 'Recreation Space', NULL, 'A luxurious recreation space designed with modern aesthetics and comfort in mind.', 'مساحة ترفيهية فاخرة مصممة بجماليات حديثة وراحة في الذهن.', '/uploads/1770307902707-0d947abeb26116a3.webp', '2023', 'Riyadh, Saudi Arabia', 'الرياض، المملكة العربية السعودية', 'Private Client', 'عميل خاص', '500 sqm', '500 متر مربع', '4 months', '6 أشهر', 'A luxurious recreation space designed with modern aesthetics and comfort in mind.', 'يمثل هذا المشروع الاستثنائي قمة التصميم الداخلي الفاخر مع التركيز على الراحة والأناقة.', 'Creating a space that balances luxury with functionality', 'كان التحدي الأساسي هو إنشاء مساحة توازن بين التصميم المعاصر والأناقة الخالدة.', 'Integrated modern design elements with premium materials', 'طورنا استراتيجية تصميم شاملة تتضمن مواد عالية الجودة وعناصر مصممة خصيصاً.', '"[\"Modern Aesthetics\",\"Premium Materials\",\"Functional Layout\",\"Ambient Lighting\"]"', '[]', '"[\"Marble\",\"Wood\",\"Glass\",\"Steel\"]"', '[]', '"[]"', '[]', '"[]"', '[]', '"[\"/TRQ STUDIO _ PROJECTS/REC. HEAVEN/13.jpg\",\"/TRQ STUDIO _ PROJECTS/REC. HEAVEN/14 c.png\",\"/TRQ STUDIO _ PROJECTS/REC. HEAVEN/22 c.png\",\"/TRQ STUDIO _ PROJECTS/REC. HEAVEN/24.png\",\"/TRQ STUDIO _ PROJECTS/REC. HEAVEN/25.png\",\"/TRQ STUDIO _ PROJECTS/REC. HEAVEN/26.png\"]"', '', NULL, '', NULL, 'published', 1, '2026-01-22 00:37:59');
