AL APARTMENT/imag2.png","/RAFAL APARTMENT/image 10.webp","/RAFAL APARTMENT/image 3.png","/RAFAL APARTMENT/image 4.webp","/RAFAL APARTMENT/image 6.webp","/RAFAL APARTMENT/image 7.webp","/RAFAL APARTMENT/image 8.webp","/RAFAL APARTMENT/image 9.webp"]', '', NULL, '', NULL, 'published', 3, '2026-01-22 00:37:59');
