INSERT INTO settings (key, value) VALUES ('aboutWhoWeAreParagraph2', 'Our multidisciplinary team brings together expertise in interior design, architecture, furniture design, and project management to deliver comprehensive solutions that exceed expectations.');
INSERT INTO settings (key, value) VALUES ('aboutWhoWeAreParagraph3', 'Whether creating intimate residential spaces or grand commercial environments, we approach each project with the same level of dedication, creativity, and attention to detail that has become our hallmark.');
INSERT INTO settings (key, value) VALUES ('aboutWhoWeAreImage', 'https://images.unsplash.com/photo-1669387448840-610c588f003d?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&w=1080');
INSERT INTO settings (key, value) VALUES ('aboutVisionIcon', 'Eye');
INSERT INTO settings (key, value) VALUES ('aboutVisionParagraph', 'To be recognized as the leading luxury design studio in Saudi Arabia and beyond, setting new standards for creative excellence and transforming spaces into timeless works of art that inspire and elevate the human experience.');
INSERT INTO settings (key, value) VALUES ('aboutMissionIcon', 'Target');
INSERT INTO settings (key, value) VALUES ('aboutMissionParagraph', 'To deliver exceptional, bespoke design solutions that reflect our clients'' unique vision while exceeding their expectations. We are committed to combining artistic innovation with practical expertise, creating spaces that are both beautiful and functional.');
